mapper.insert:
insert into notification_fanout_job (
    event_id, actor_id, solution_id, occurred_at, cursor_user_id, status,
    lease_owner, lease_until, attempts, next_attempt_at, last_error, created_at, updated_at
) values (
    #{job.eventId}, #{job.actorId}, #{job.solutionId}, #{job.occurredAt}, #{job.cursorUserId},
    #{job.status}, #{job.leaseOwner}, #{job.leaseUntil}, #{job.attempts}, #{job.nextAttemptAt},
    #{job.lastError}, #{job.createdAt}, #{job.updatedAt}
) on duplicate key update event_id = values(event_id)

mapper.update:
update notification_fanout_job
set status = 'SENDING',
    lease_owner = #{leaseOwner},
    lease_until = #{leaseUntil},
    attempts = attempts + 1,
    updated_at = #{now}
where event_id = #{eventId}
  and next_attempt_at <= #{now}
  and attempts < 20
  and (status = 'PENDING' or (status = 'SENDING' and lease_until <= #{now}))

update notification_fanout_job
set cursor_user_id = #{cursorUserId},
    status = #{status},
    lease_owner = null,
    lease_until = null,
    attempts = case when #{status} = 'PENDING' then 0 else attempts end,
    next_attempt_at = #{now},
    last_error = null,
    updated_at = #{now}
where event_id = #{eventId}
  and status = 'SENDING'
  and lease_owner = #{leaseOwner}
  and lease_until > #{now}

update notification_fanout_job
set status = #{status},
    next_attempt_at = #{nextAttemptAt},
    lease_owner = null,
    lease_until = null,
    last_error = #{errorCode},
    updated_at = #{now}
where event_id = #{eventId}
  and status = 'SENDING'
  and lease_owner = #{leaseOwner}
  and lease_until > #{now}

mapper.select:
select status
from notification_fanout_job
where event_id = #{eventId}

mapper.delete:
delete from notification_fanout_job
where status = 'DONE'
  and updated_at < #{completedBefore}
order by updated_at asc, event_id asc
limit #{limit}
